import{_ as e,o as l,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-12-03 -- Ceph Testing Meeting","description":"","frontmatter":{"title":"2019-12-03 -- Ceph Testing Meeting","date":"2019-12-03T00:00:00.000Z","updated":"2019-12-05T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH 算法","高可用性","可伸缩性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-12-03_-_-_Ceph_Testing_Meeting.md","filePath":"posts/2019/2019-12-03_-_-_Ceph_Testing_Meeting.md","lastUpdated":1780460162000}'),n={name:"posts/2019/2019-12-03_-_-_Ceph_Testing_Meeting.md"};function s(o,i,u,r,h,p){return l(),t("div",null,[...i[0]||(i[0]=[a('<p>会议纪要</p><h3 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h3><p>本次Ceph测试会议主要讨论了Ceph存储系统各分支（如Nautilus、Luminous等）的开发状态、Python 3迁移、以及后续的测试和发布计划。</p><h3 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h3><ol><li><p><strong>Nautilus分支状态</strong>：</p><ul><li>由Sage和David负责升级和测试，即将发布。</li><li>讨论了Nautilus的发布笔记和向后兼容性问题。</li></ul></li><li><p><strong>Luminous分支的Python 3迁移</strong>：</p><ul><li>正在处理几个PR，需要进行测试。</li><li>讨论了Luminous分支的Python 3迁移状态和测试需求。</li></ul></li><li><p><strong>Master分支的兼容性和测试</strong>：</p><ul><li>讨论了Master分支与Python 3的兼容性问题。</li><li>讨论了Jenkins实例中使用的CentOS 7.6和7.8镜像的需求。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>决定对Nautilus、Mimic和Luminous分支进行Python 3的向后移植。</li><li>讨论了如何处理分支的测试和发布，特别是关于旧版本的向后兼容性问题。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>关注Nautilus的发布笔记和向后兼容性。</li><li>进行Luminous分支的Python 3迁移测试。</li><li>为Master分支准备更多的CentOS镜像以支持测试。</li><li>对Nautilus、Mimic和Luminous进行Python 3的向后移植，并确保这些分支的稳定性和兼容性。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>Yuri将继续处理Luminous分支的PR，并添加测试标签。</li><li>Pierre将负责Nautilus分支的PR工作。</li><li>为Master分支准备更多的CentOS镜像。</li><li>对Nautilus、Mimic和Luminous进行Python 3的向后移植，并确保这些分支的稳定性和兼容性。</li></ul><h3 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h3><ul><li>讨论了Ceph的发布周期和命名规则，下一个版本将是Octopus。</li><li>讨论了资源锁定机制和测试套件的优化问题。</li><li>讨论了Ceph的升级测试套件的复杂性，以及如何减少资源锁定的需求。</li><li>讨论了Ceph在不同操作系统上的测试需求。</li></ul><p>会议在讨论了所有议题后结束，团队成员将继续按照会议决定的事项推进工作。</p>',12)])])}const c=e(n,[["render",s]]);export{d as __pageData,c as default};
